color_echo "green" "Papirus Icon Theme installed successfully."

# Custom user-defined commands
echo "Created with ❤️ for Open Source"

# INSTALL ZINIT and copy dotfiles for ACTUAL_USER
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
SOURCE_DOTFILES_DIR="${1:-$SCRIPT_DIR/dotfiles}"
TARGET_CONFIG_DIR="$ACTUAL_HOME/.config"
ZINIT_HOME="$ACTUAL_HOME/.local/share/zinit/zinit.git"
BACKUP_DIR="$ACTUAL_HOME/.dotfiles_backup_$(date +%Y%m%d_%H%M%S)"

if [[ ! -d "$SOURCE_DOTFILES_DIR" ]]; then
    color_echo "red" "Error: Source directory '$SOURCE_DOTFILES_DIR' does not exist."
    FAILURES=$((FAILURES+1))
    log_message "FAILED: Dotfiles directory '$SOURCE_DOTFILES_DIR' not found"
else
    # 1. Install Zinit as the actual user (non-interactively) before copying .zshrc
    if [[ ! -d "$ZINIT_HOME" ]]; then
        color_echo "yellow" "Installing Zinit for $ACTUAL_USER..."
        sudo -u "$ACTUAL_USER" env HOME="$ACTUAL_HOME" NO_INPUT=1 \
            bash -c "$(curl --fail --show-error --silent --location https://raw.githubusercontent.com/zdharma-continuum/zinit/HEAD/scripts/install.sh)"
        color_echo "green" "Zinit installed successfully."
    else
        color_echo "blue" "Zinit is already installed at '$ZINIT_HOME', skipping."
    fi

    # 2. Copy top-level dotfiles (.zshrc, .zsh_aliases, etc.) excluding .config
    shopt -s dotglob nullglob
    for item in "$SOURCE_DOTFILES_DIR"/*; do
        name="$(basename "$item")"
        if [[ "$name" == ".config" ]]; then
            continue
        fi

        target="$ACTUAL_HOME/$name"
        if [[ -e "$target" || -L "$target" ]]; then
            mkdir -p "$BACKUP_DIR"
            mv "$target" "$BACKUP_DIR/"
        fi
        cp -a "$item" "$target"
    done

    # 3. Copy everything inside dotfiles/.config/ (kitty/, starship.toml, etc.)
    if [[ -d "$SOURCE_DOTFILES_DIR/.config" ]]; then
        mkdir -p "$TARGET_CONFIG_DIR"
        for cfg in "$SOURCE_DOTFILES_DIR/.config"/*; do
            cfg_name="$(basename "$cfg")"
            target_cfg="$TARGET_CONFIG_DIR/$cfg_name"
            if [[ -e "$target_cfg" || -L "$target_cfg" ]]; then
                mkdir -p "$BACKUP_DIR/.config"
                mv "$target_cfg" "$BACKUP_DIR/.config/"
            fi
            cp -a "$cfg" "$target_cfg"
        done
    fi
    shopt -u dotglob nullglob

    # 4. Fix ownership so ACTUAL_USER owns all copied configs, Zinit files, and backups
    mkdir -p "$TARGET_CONFIG_DIR" "$ACTUAL_HOME/.local"
    chown -R "$ACTUAL_USER:$ACTUAL_USER" "$TARGET_CONFIG_DIR" "$ACTUAL_HOME/.local"
    shopt -s dotglob nullglob
    for item in "$SOURCE_DOTFILES_DIR"/*; do
        name="$(basename "$item")"
        if [[ "$name" != ".config" && ( -e "$ACTUAL_HOME/$name" || -L "$ACTUAL_HOME/$name" ) ]]; then
            chown -hR "$ACTUAL_USER:$ACTUAL_USER" "$ACTUAL_HOME/$name"
        fi
    done
    shopt -u dotglob nullglob
    if [[ -d "$BACKUP_DIR" ]]; then
        chown -R "$ACTUAL_USER:$ACTUAL_USER" "$BACKUP_DIR"
    fi

    # 5. Restore SELinux contexts
    if command -v restorecon &>/dev/null; then
        restorecon -RF "$TARGET_CONFIG_DIR" "$ACTUAL_HOME/.local/share/zinit" 2>/dev/null || true
    fi

    # 6. Set Zsh as default shell for ACTUAL_USER
    if command -v zsh &>/dev/null; then
        chsh -s "$(command -v zsh)" "$ACTUAL_USER"
    fi

    color_echo "green" "Dotfiles copied to $ACTUAL_HOME (backups in $BACKUP_DIR if replaced)."
fi

# Configure lazygit and lazydocker (if not already provided by dotfiles)
color_echo "yellow" "Configuring lazygit and lazydocker..."
LAZYGIT_CONFIG_DIR="$ACTUAL_HOME/.config/lazygit"
LAZYDOCKER_CONFIG_DIR="$ACTUAL_HOME/.config/lazydocker"
mkdir -p "$LAZYGIT_CONFIG_DIR" "$LAZYDOCKER_CONFIG_DIR"

if [[ ! -f "$LAZYGIT_CONFIG_DIR/config.yml" ]]; then
    cat << 'EOF' > "$LAZYGIT_CONFIG_DIR/config.yml"
gui:
  nerdFontsVersion: "3"
  border: "rounded"
  showFileTree: true
  showRandomTip: false
  showBottomLine: true
  expandFocusedSidePanel: true
  sidePanelWidth: 0.3333
git:
  autoFetch: true
  autoRefresh: true
  parseEmoji: true
confirmOnQuit: false
quitOnTopLevelReturn: false
EOF
    color_echo "green" "Created default lazygit config at $LAZYGIT_CONFIG_DIR/config.yml"
