gui:
  returnImmediately: true
  wrapMainPanel: true
  border: "rounded"
  showAllContainers: true
logs:
  timestamps: false
  since: "60m"
  tail: "300"
commandTemplates:
  dockerCompose: "docker compose"
EOF
    color_echo "green" "Created default lazydocker config at $LAZYDOCKER_CONFIG_DIR/config.yml"
else
